cssOut:
:root{
  --teal:#00acac;
  --teal-dark:#029191;
  --navy:#101c26;
  --sidebar:#263f50;
  --sidebar-active:#1c2f3c;
  --bg:#E9EAED;
  --card:#ffffff;
  --ink:#24344a;
  --body:#474747;
  --muted:#8a94a0;
  --line:#e6eaef;
  --red:#e53935;
  --radius:14px;
  --shadow:0 1px 2px rgba(16,32,48,.06),0 8px 24px -14px rgba(16,32,48,.22);
}
html{scroll-behavior:smooth}
body{
  font-family:"Segoe UI",Inter,system-ui,-apple-system,Roboto,"Helvetica Neue",Arial,sans-serif;
  background:
    radial-gradient(1100px 560px at 88% -8%, rgba(0,172,172,.06), transparent 60%),
    radial-gradient(900px 520px at -8% 34%, rgba(3,45,96,.04), transparent 55%),
    var(--bg);
  color:var(--body);
  display:flex;
  min-height:100vh;
  font-size:15px;
  -webkit-font-smoothing:antialiased;
}
.avatar svg{width:55%;height:55%}
.avatar.lg{width:78px;height:78px;font-size:25px;border:4px solid #fff}
.av-rc{background:linear-gradient(135deg,#00acac,#026e8f)}
.av-brand{background:linear-gradient(150deg,#152430,#0b1620)}
.av-lf{background:linear-gradient(135deg,#f06292,#ad1457)}
.av-wm{background:linear-gradient(135deg,#5c6bc0,#283593)}
.av-gc{background:linear-gradient(135deg,#ffb74d,#ef6c00)}
.av-ms{background:linear-gradient(135deg,#26a69a,#00695c)}
.av-bo{background:linear-gradient(135deg,#ff8a65,#d84315)}
.av-as{background:linear-gradient(135deg,#ba68c8,#6a1b9a)}
.av-pl{background:linear-gradient(135deg,#4fc3f7,#0277bd)}
.av-cm{background:linear-gradient(135deg,#9ccc65,#558b2f)}
.av-js{background:linear-gradient(135deg,#90a4ae,#37474f)}
.av-rc,.av-lf,.av-wm,.av-gc,.av-ms,.av-bo,.av-as,.av-pl,.av-cm,.av-js{color:transparent;text-shadow:none}
.av-rc{background:url("uploads/people/rodrigo.png") center/cover}
.av-lf{background:url("uploads/people/ana-elis.png") center/cover}
.av-wm{background:url("uploads/people/guilherme-reis.png") center/cover}
.av-gc{background:url("uploads/people/ellen.png") center/cover}
.av-ms{background:url("uploads/people/matheus.jpg") center/cover}
.av-bo{background:url("uploads/people/eduardo.png") center/cover}
.av-as{background:url("uploads/people/paola.png") center/cover}
.av-pl{background:url("uploads/people/guilherme.png") center/cover}
.av-cm{background:url("uploads/people/gisele.png") center/cover}
.av-js{background:url("uploads/people/eduardo.png") center/cover}
@keyframes newIn{from{opacity:0;transform:scale(.98)}to{opacity:1;transform:scale(1)}}
@keyframes sheetIn{from{opacity:0;transform:translateY(100%)}to{opacity:1;transform:none}}
.toast{
  display:flex;align-items:center;gap:12px;background:#12C55B;border:0;color:#fff;
  border-radius:6px;padding:13px 16px;min-width:280px;
  box-shadow:0 4px 16px rgba(0,0,0,.1);animation:toastIn .2s cubic-bezier(.4,0,.2,1);
}
@keyframes toastIn{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}
.toast.out{animation:toastOut .2s cubic-bezier(.4,0,.2,1) forwards}
@keyframes toastOut{to{opacity:0;transform:translateY(-10px)}}
.toast .tk{width:30px;height:30px;border-radius:50%;background:rgba(255,255,255,.18);color:#fff;
  display:flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0}
.toast .tt{flex:1;font-size:13.5px;font-weight:600;color:#fff}
.toast .tv{color:#fff;font-size:13px;font-weight:700}
.toast .tv:hover{text-decoration:underline}
@keyframes tshimmer{to{transform:translateX(100%)}}
@keyframes nfFlash{0%{background:rgba(0,172,172,.22)}100%{background:rgba(0,172,172,.06)}}
@keyframes jiggle{
  0%{transform:rotate(-1.4deg) translate(-.5px,.5px)}
  50%{transform:rotate(1.4deg) translate(.5px,-.5px)}
  100%{transform:rotate(-1.7deg)}
}
.fo-btn{display:inline-flex;align-items:center;gap:8px;background:var(--teal);color:#fff;font-size:13px;font-weight:700;padding:10px 16px;border-radius:999px;border:0;cursor:pointer;transition:background .15s}
.fo-btn:hover{background:#029191}
.fo-btn.ghost{background:#fff;color:#5b6672;border:1.5px solid var(--line)}
.fo-btn.ghost:hover{background:#f2f5f7}
.fg-backdrop.open{display:flex}
.fg-modal{width:560px;max-width:100%;max-height:92vh;overflow-y:auto;background:#fff;border-radius:18px;box-shadow:0 30px 70px -20px rgba(16,32,48,.5)}
.fg-head{display:flex;align-items:center;gap:14px;padding:18px 22px;border-bottom:1px solid var(--line)}
.fg-head h2{font-size:17px;font-weight:800;color:var(--ink)}
.fg-steps{display:flex;gap:8px;margin-left:auto}
.fg-step{font-size:11px;font-weight:700;color:var(--muted);display:flex;align-items:center;gap:6px}
.fg-step .n{width:20px;height:20px;border-radius:50%;background:#eef1f4;color:var(--muted);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800}
.fg-step.on{color:var(--teal)}
.fg-step.on .n{background:var(--teal);color:#fff}
.fg-close{background:none;border:0;color:var(--muted);font-size:18px;cursor:pointer}
.fg-body{padding:20px 22px}
.fg-pane{display:none}
.fg-pane.on{display:block}
.fg-field{margin-bottom:16px}
.fg-label{font-size:12.5px;font-weight:700;color:var(--ink);margin-bottom:6px;display:block}
.fg-input,.fg-textarea{width:100%;border:1.5px solid var(--line);border-radius:10px;padding:10px 12px;font:inherit;font-size:13.5px;color:var(--ink);outline:none}
.fg-input:focus,.fg-textarea:focus{border-color:var(--teal)}
.fg-textarea{resize:vertical;min-height:64px}
.fg-swatches,.fg-icons{display:flex;flex-wrap:wrap;gap:9px}
.fg-sw{width:30px;height:30px;border-radius:50%;cursor:pointer;border:2px solid transparent;display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px}
.fg-sw.on{border-color:#fff;box-shadow:0 0 0 2px var(--ink)}
.fg-ic{width:38px;height:38px;border-radius:10px;border:1.5px solid var(--line);background:#fff;color:#5b6672;cursor:pointer;font-size:15px}
.fg-ic.on{border-color:var(--teal);color:var(--teal);background:rgba(0,172,172,.08)}
.fg-preview{margin-top:6px}
.fg-radio{display:flex;gap:12px;padding:14px;border:1.5px solid var(--line);border-radius:12px;cursor:pointer;margin-bottom:10px}
.fg-radio.on{border-color:var(--teal);background:rgba(0,172,172,.05)}
.fg-radio .dot{width:18px;height:18px;border-radius:50%;border:2px solid var(--line);flex-shrink:0;margin-top:1px}
.fg-radio.on .dot{border-color:var(--teal);background:radial-gradient(circle,var(--teal) 40%,#fff 45%)}
.fg-radio .rt{font-size:13.5px;font-weight:700;color:var(--ink)}
.fg-radio .rd{font-size:12px;color:var(--muted);margin-top:2px}
.fg-check{display:flex;align-items:center;gap:9px;font-size:13px;color:var(--ink);padding:7px 0;cursor:pointer}
.fg-check input{width:16px;height:16px;accent-color:var(--teal)}
.fg-count{font-size:13px;font-weight:700;color:var(--teal);background:rgba(0,172,172,.08);border-radius:10px;padding:11px 14px;margin:8px 0}
.fg-toggle{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--ink);padding:9px 0;cursor:pointer}
.fg-sw2{width:38px;height:22px;border-radius:999px;background:#cfd8df;position:relative;transition:background .15s;flex-shrink:0}
.fg-sw2::after{content:'';position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:#fff;transition:transform .15s}
.fg-toggle.on .fg-sw2{background:var(--teal)}
.fg-toggle.on .fg-sw2::after{transform:translateX(16px)}
.fg-foot{display:flex;gap:10px;padding:16px 22px;border-top:1px solid var(--line)}
.fg-foot .sp{flex:1}
.cat-add{display:inline-flex;align-items:center;gap:8px;background:var(--teal);color:#fff;border:0;border-radius:999px;padding:10px 17px;font:inherit;font-size:13px;font-weight:700;cursor:pointer;transition:background .15s}
.cat-add:hover{background:var(--teal-dark)}
.fo-btn.ghost{background:#eef2f5;color:#5b6672}
.fo-btn.ghost:hover{background:#e2e8ee;color:var(--ink)}
.cr-spin{width:44px;height:44px;border-radius:50%;border:3px solid #E9EAED;border-top-color:#00ACAC;animation:crspin .8s linear infinite}
@keyframes crspin{to{transform:rotate(360deg)}}
.nv-dtrow{display:flex;gap:8px;margin-top:10px}
.nv-dtrow input{height:42px;padding:0 12px;border:0;border-radius:8px;background:#fff;box-shadow:inset 0 0 0 1px #D1D1D6;font:inherit;font-size:14px;letter-spacing:.3px;color:#1C1C1E}
.nv-dtrow input[type="date"]{flex:1;min-width:0;max-width:none;padding:0 12px;font-size:14px;border:0;border-radius:8px}
.nv-dtrow input[type="time"]{width:110px;flex-shrink:0}
.nv-dtrow input:focus{outline:none;box-shadow:inset 0 0 0 1px #0088FF,0 0 0 2px rgba(0,136,255,.16)}
#crShare:disabled{background:#F4F5F6;color:#C7C7CC;cursor:default;box-shadow:none}
.cr-audwrap{position:relative;flex-shrink:0}
.cr-audwrap .qp-aud{margin-top:0;height:36px;padding:0 14px;font-size:13px}
.cr-audwrap .qp-catmenu{left:auto;right:0;min-width:220px}
.cr-catwrap{margin:0;position:relative;display:block}
.cr-catwrap .qp-cat{width:100%;justify-content:flex-start;height:42px;position:relative;padding-right:36px}
.cr-catwrap .qp-cat>.fa-chevron-down{position:absolute;right:14px;top:50%;transform:translateY(-50%)}
.cr-catwrap .qp-catmenu{left:0;right:0;min-width:0}
.nv-def-wrap{max-width:900px;margin:0;display:flex;flex-direction:column;gap:4px}
.nv-def-row{display:flex;align-items:flex-start;gap:24px;padding:20px 0;border-bottom:1px solid var(--line)}
.nv-def-row:last-child{border-bottom:0}
.nv-def-lbl{width:260px;flex-shrink:0;padding-top:2px}
.nv-def-lbl b{display:block;font-size:16px;color:var(--ink);font-weight:700}
.nv-def-lbl span{display:block;font-size:14px;color:var(--muted);margin-top:4px;line-height:1.45}
.nv-def-ctl{flex:1;min-width:0}
.nv-def-ctl select,.nv-def-ctl input[type=date]{width:100%;max-width:300px;font:inherit;font-size:15px;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:9px;padding:11px 14pxx;cursor:pointer;outline:none}
.nv-def-ctl select:focus,.nv-def-ctl input[type=date]:focus{border-color:var(--teal);box-shadow:0 0 0 3px rgba(0,172,172,.14)}
.nv-toggle{position:relative;display:inline-flex;align-items:center;gap:11px;cursor:pointer;font-size:15px;color:#465364}
.nv-toggle input{position:absolute;opacity:0;width:0;height:0}
.nv-toggle .nv-tk{width:42px;height:24px;border-radius:999px;background:#cdd6de;transition:background .15s;flex-shrink:0;position:relative}
.nv-toggle .nv-tk::after{content:'';position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .15s;box-shadow:0 1px 3px rgba(0,0,0,.25)}
.nv-toggle input:checked + .nv-tk{background:var(--teal)}
.nv-toggle input:checked + .nv-tk::after{transform:translateX(18px)}
.nv-def-sec{font-size:13px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:var(--teal);margin:26px 0 2px}
.nv-def-sec:first-child{margin-top:6px}
.nv-seg2{display:inline-flex;background:#eef2f5;border-radius:10px;padding:3px;gap:2px}
.nv-seg2 button{border:0;background:none;cursor:pointer;font:inherit;font-size:12.5px;font-weight:700;color:var(--muted);padding:7px 15px;border-radius:8px;transition:all .15s}
.nv-seg2 button.on{background:#fff;color:var(--ink);box-shadow:0 2px 5px -2px rgba(16,32,48,.3)}
.qp-back.open{display:flex}
.qp-modal{width:min(720px,100%);max-height:94vh;background:#fff;border-radius:14px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.4)}
.qp-head{display:flex;align-items:center;gap:12px;padding:16px 20px}
.qp-head .avatar{width:48px;height:48px;font-size:0;flex-shrink:0}
.qp-head b{font-size:15px;color:var(--ink);display:block}
.qp-aud{display:inline-flex;align-items:center;gap:8px;height:28px;margin-top:6px;font-size:13px;line-height:18px;font-weight:600;letter-spacing:.3px;color:var(--ink);background:#fff;box-shadow:inset 0 0 0 1px var(--line);border:0;border-radius:32px;padding:0 12px;cursor:pointer}
.qp-aud .fa-chevron-down{font-size:11px !important}
.qp-aud{transition:background 120ms cubic-bezier(.4,0,.2,1),color 120ms cubic-bezier(.4,0,.2,1)}
.qp-aud:hover{box-shadow:inset 0 0 0 1px var(--teal)}
.qp-aud>.fa-earth-americas,.qp-aud>.fa-store,.qp-aud>.fa-building{color:#1667B8}
.qp-aud:focus-visible{outline:none;box-shadow:0 0 0 2px rgba(0,136,255,.16)}
.qp-x{width:38px;height:38px;border:0;background:none;border-radius:50%;color:#5b6672;font-size:18px;cursor:pointer;flex-shrink:0}
.qp-cat{margin-left:auto;display:inline-flex;align-items:center;gap:9px;font:inherit;font-size:13px;font-weight:700;color:var(--ink);background:#fff;border:1px solid var(--line);border-radius:999px;padding:8px 14px;cursor:pointer;outline:none}
.qp-cat:hover{border-color:var(--teal)}
.qp-cat-ic{width:22px;height:22px;border-radius:7px;display:flex;align-items:center;justify-content:center;color:#fff;font-size:11px;flex-shrink:0}
.qp-audwrap{position:relative}
.qp-audmenu{left:0;right:auto;min-width:250px}
.qp-audmenu button{gap:10px}
.qp-audmenu button>i{width:16px;font-size:13px;color:#8E8E93;text-align:center;flex-shrink:0}
.qp-audmenu button:hover>i{color:#48484A}
.qp-catwrap{margin-left:auto;position:relative;margin-right:16px}
.qp-catwrap .qp-cat{margin-left:0}
.qp-catmenu{position:absolute;top:calc(100% + 6px);right:0;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 14px 34px -12px rgba(16,32,48,.4);padding:6px;z-index:10;min-width:220px;max-height:280px;overflow-y:auto}
.qp-catmenu button{display:flex;align-items:center;gap:10px;width:100%;border:0;background:none;padding:9px 10px;border-radius:8px;font:inherit;font-size:13px;font-weight:600;color:#465364;cursor:pointer;text-align:left}
.qp-catmenu button:hover{background:#f3f6f9}
.qp-catmenu .qp-cat-ic{width:24px;height:24px;font-size:12px}
.qp-x+.qp-x{margin-left:0}
.qp-x:hover{background:#f0f3f6;color:var(--ink)}
.qp-body{flex:1;overflow-y:auto;padding:4px 24px 8px;min-height:300px;display:flex;flex-direction:column}
.qp-text{flex:1;border:0;outline:none;resize:none;font:inherit;font-size:20px;line-height:1.5;color:var(--ink);min-height:280px;padding:8px 0}
.qp-text::placeholder{color:#9aa7b3}
.qp-body.colored{border-radius:12px;padding:24px;margin:4px 20px 8px;align-items:center;justify-content:center}
.qp-bigemoji{display:none;border:0;background:rgba(255,255,255,.16);width:74px;height:74px;border-radius:50%;font-size:38px;cursor:pointer;align-items:center;justify-content:center;margin-bottom:14px;color:#fff}
.qp-bigemoji:hover{background:rgba(255,255,255,.26)}
.qp-body.colored .qp-text{flex:0 0 auto;min-height:auto;font-size:26px;font-weight:800}
.qp-body.colored .qp-text{background:transparent;color:#fff;text-align:center;font-size:26px;font-weight:800;min-height:auto;flex:0 0 auto;display:block;padding:0}
.qp-body.colored .qp-text::placeholder{color:rgba(255,255,255,.85)}
.qp-sub{border:0;outline:none;background:transparent;font:inherit;font-size:16px;font-weight:600;color:#fff;text-align:center;width:100%;margin-top:10px}
.qp-sub::placeholder{color:rgba(255,255,255,.7)}
.qp-colors{display:flex;gap:9px;padding:4px 20px 12px;flex-wrap:wrap}
.qp-colors.hidden{display:none}
.qp-color{width:34px;height:34px;border-radius:9px;cursor:pointer;border:2px solid transparent;transition:transform .1s}
.qp-color:hover{transform:scale(1.08)}
.qp-color.sel{box-shadow:0 0 0 2px #fff,0 0 0 4px var(--ink)}
.qp-color.none{background:#fff;border:2px solid var(--line);display:flex;align-items:center;justify-content:center;color:#8a94a0;font-size:13px}
.qp-color.custom{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;background:conic-gradient(from 0deg,#f00,#ff0,#0f0,#0ff,#00f,#f0f,#f00)}
.qp-color.custom input{position:absolute;inset:0;opacity:0;cursor:pointer}
.qp-imgwrap{position:relative;margin-top:14px;border-radius:12px;overflow:hidden}
.qp-imgwrap img{width:100%;display:block;border-radius:12px}
.qp-imgx{position:absolute;top:10px;right:10px;width:32px;height:32px;border-radius:50%;background:rgba(0,0,0,.6);color:#fff;display:flex;align-items:center;justify-content:center;font-size:13px;cursor:pointer}
.qp-imggrid{display:grid;gap:4px;margin-top:14px;border-radius:12px;overflow:hidden;grid-auto-rows:150px}
.qp-imggrid.n1{grid-auto-rows:auto}
.qp-imggrid.n1{grid-template-columns:1fr}
.qp-imggrid.n2{grid-template-columns:1fr 1fr}
.qp-imggrid.n3{grid-template-columns:1fr 1fr}
.qp-imggrid.n3 .qp-imgcell:first-child{grid-column:1/-1}
.qp-imggrid.n4{grid-template-columns:1fr 1fr}
.qp-imgcell{position:relative;overflow:hidden;background:#000}
.qp-imggrid.n1 .qp-imgcell{max-height:380px}
.qp-imgcell img{width:100%;height:100%;object-fit:cover;display:block}
.qp-imggrid.n1 .qp-imgcell img{height:auto;max-height:380px}
.qp-imgcell[draggable=true]{cursor:grab}
.qp-imgcell.dragging{opacity:.4}
.qp-imgmore{position:absolute;inset:0;background:rgba(0,0,0,.55);color:#fff;font-size:26px;font-weight:800;display:flex;align-items:center;justify-content:center}
.qp-imgdel{position:absolute;top:6px;right:6px;width:26px;height:26px;border-radius:50%;background:rgba(0,0,0,.6);color:#fff;display:flex;align-items:center;justify-content:center;font-size:11px;cursor:pointer;border:0}
.ie-modal{width:min(1000px,100%);height:min(680px,92vh);background:#fff;border-radius:14px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.4)}
.ie-head{display:flex;align-items:center;padding:16px 22px;border-bottom:1px solid var(--line)}
.ie-head h2{font-size:19px;font-weight:800;color:var(--ink);flex:1}
.ie-close{width:38px;height:38px;border:0;background:none;border-radius:50%;color:#5b6672;font-size:17px;cursor:pointer}
.ie-close:hover{background:#f0f3f6}
.ie-body{flex:1;min-height:0;display:flex}
.ie-main{flex:1;background:#f7f9fa;display:flex;align-items:center;justify-content:center;padding:20px}
.ie-main img{max-width:100%;max-height:100%;border-radius:6px}
.ie-side{width:340px;flex-shrink:0;border-left:1px solid var(--line);display:flex;flex-direction:column;padding:18px}
.ie-count{font-size:13px;color:var(--muted);font-weight:700;margin-bottom:12px}
.ie-thumbs{flex:1;overflow-y:auto;display:grid;grid-template-columns:1fr 1fr;gap:14px;align-content:start}
.ie-thumb{position:relative;border:2px solid transparent;border-radius:10px;overflow:hidden;cursor:pointer;background:#eef2f5}
.ie-thumb.sel{border-color:var(--teal);box-shadow:0 0 0 3px rgba(0,172,172,.2)}
.ie-thumb img{width:100%;height:96px;object-fit:cover;display:block}
.ie-thumb .ie-n{position:absolute;bottom:4px;left:6px;font-size:11px;font-weight:800;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.6)}
.ie-thumb .ie-mv{position:absolute;top:50%;transform:translateY(-50%);width:30px;height:30px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;border:0;display:none;align-items:center;justify-content:center;font-size:12px;cursor:pointer}
.ie-thumb:hover .ie-mv{display:flex}
.ie-mv.l{left:6px}
.ie-mv.r{right:6px}
.ie-tools{display:flex;align-items:center;justify-content:flex-end;gap:14px;padding-top:14px;border-top:1px solid var(--line);margin-top:12px}
.ie-tools button{width:38px;height:38px;border:0;background:none;border-radius:8px;color:#5b6672;font-size:16px;cursor:pointer}
.ie-tools button:hover{background:#f0f3f6;color:var(--ink)}
.ie-tools button.round{border:1.5px solid var(--line);border-radius:50%}
.ie-foot{display:flex;justify-content:flex-end;padding:14px 22px;border-top:1px solid var(--line)}
.qp-tools{position:relative;display:flex;align-items:center;gap:4px;padding:12px 16px;border-top:1px solid var(--line)}
.qp-emojis{position:absolute;bottom:52px;left:12px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 14px 34px -12px rgba(16,32,48,.4);padding:10px;display:grid;grid-template-columns:repeat(8,1fr);gap:2px;z-index:5}
.qp-emojis span{width:34px;height:34px;display:flex;align-items:center;justify-content:center;font-size:19px;cursor:pointer;border-radius:8px}
.qp-emojis span:hover{background:#f0f3f6}
.qp-tool{display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 14px;border:0;background:none;border-radius:8px;color:#5b6672;font:inherit;font-size:13.5px;font-weight:600;cursor:pointer}
.qp-tool i{font-size:17px}
.qp-tool:hover{background:#f0f3f6;color:var(--ink)}
.qp-tool.color.on i{color:#00acac}
.qp-foot{display:flex;align-items:center;gap:12px;padding:12px 20px;border-top:1px solid var(--line)}
.qp-adv{border:0;background:none;font:inherit;font-size:13px;font-weight:700;color:#8161d8;cursor:pointer;display:inline-flex;align-items:center;gap:7px}
.qp-adv:hover{text-decoration:underline}
.qp-adv.on{color:#00acac}
.cr-cover{position:absolute;top:24px;right:24px;z-index:1;display:inline-flex;align-items:center;gap:7px;
  height:32px;padding:0 14px;border:0;border-radius:32px;background:rgba(28,28,30,.62);color:#fff;
  font:inherit;font-size:13px;line-height:18px;font-weight:600;letter-spacing:.3px;cursor:pointer;
  transition:background 120ms cubic-bezier(.4,0,.2,1)}
.cr-cover i{font-size:12px}
.cr-cover:hover{background:rgba(28,28,30,.78)}
.cr-cover:focus-visible{outline:none;box-shadow:0 0 0 2px rgba(0,136,255,.16)}
.cr-advover{position:absolute;inset:0;z-index:3;background:#fff;display:flex;flex-direction:column}
.cr-advover[hidden]{display:none}
.cr-advhd{display:flex;align-items:center;gap:12px;height:56px;flex-shrink:0;padding:0 20px;box-shadow:inset 0 -1px 0 #E9EAED;font-size:15px;font-weight:600;letter-spacing:.3px;color:#1C1C1E}
.cr-advback{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 14px;border:0;border-radius:4px;background:#F4F5F6;color:#48484A;font:inherit;font-size:14px;line-height:20px;font-weight:600;letter-spacing:.3px;cursor:pointer}
.cr-advback:hover{background:linear-gradient(rgba(28,28,30,.08),rgba(28,28,30,.08)),#F4F5F6;color:#1C1C1E}
.cr-advbody{flex:1;min-height:0;overflow-y:auto;padding:8px 24px 20px}
.cr-advbody .nv-def-wrap{max-width:none;margin:0}
.cr-advbody .nv-def-row{padding:16px 0}
.qp-advpanel{padding:0 24px 12px;overflow-y:auto;max-height:52vh}
.qp-advhd{margin:0 -24px 8px;padding:0 24px}
.qp-advpanel .nv-def-wrap{max-width:none;margin:0}
.qp-advpanel .nv-def-row{padding:16px 0}
.qp-advpanel .nv-def-lbl{width:230px}
.qp-pub{margin-left:auto;border:0;border-radius:999px;padding:11px 26px;font:inherit;font-size:14px;font-weight:700;background:var(--teal);color:#fff;cursor:pointer}
.qp-pub:disabled{background:#c4ccd4;cursor:default}
.rx-search{flex:1;max-width:460px;display:flex;align-items:center;gap:12px;background:#f4f6f8;
  border:1.5px solid #e6eaef;border-radius:999px;padding:12px 20px;transition:border-color .15s,background .15s,box-shadow .15s}
.rx-search:hover{background:#eef2f5}
.rx-search:focus-within{background:#fff;border-color:var(--teal);box-shadow:0 0 0 4px rgba(0,172,172,.13)}
.rx-search i{transition:color .15s}
.rx-search:focus-within i{color:var(--teal)}
.rx-search i{font-size:14px;color:var(--muted)}
.rx-search input{border:0;background:none;outline:none;flex:1;font:inherit;font-size:14.5px;color:var(--ink)}
.rx-search input::placeholder{color:#9aa7b3}
@keyframes rvTick{from{width:0}to{width:100%}}
@keyframes tshimmerP{to{transform:translateX(100%)}}
@keyframes tcardIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
body.demo-empty .demo-filled{display:none}
body.demo-empty .demo-empty-state{display:flex}
@keyframes deSpin{to{transform:rotate(360deg)}}
@keyframes svIn{from{transform:scale(.95);opacity:0}to{transform:scale(1);opacity:1}}
@keyframes rbPop{
  0%{opacity:0;transform:scale(.4) translateY(8px)}
  55%{opacity:1;transform:scale(1.05) translateY(-2px)}
  100%{opacity:1;transform:scale(1) translateY(0)}
}
@keyframes rbPunch{
  0%{transform:scale(1.34) translateY(-14px);opacity:1}
  35%{transform:scale(1.62) translateY(-22px);opacity:1}
  100%{transform:scale(.45) translateY(8px);opacity:0}
}
@keyframes rxvIn{from{transform:scale(.96);opacity:0}to{transform:scale(1);opacity:1}}
@keyframes commentIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
@keyframes itblPulse{0%{box-shadow:0 0 0 0 rgba(0,172,172,.55)}70%{box-shadow:0 0 0 6px rgba(0,172,172,0)}100%{box-shadow:0 0 0 0 rgba(0,172,172,0)}}
.qp-start,.nvf-start{font-size:15px}
.nvf-qbtn,.qp-tool{font-size:14px}

